import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const disposables = [];

  // Load background image texture
  const bgTexture = ctx.textureLoader.load(config.assets.imageUrl);
  bgTexture.colorSpace = THREE.SRGBColorSpace;
  disposables.push(bgTexture);

  // Create plane geometry with aspect ratio matching atlas (512×320)
  const planeGeo = new THREE.PlaneGeometry(512 / 320, 1);
  disposables.push(planeGeo);

  // Material using TSL texture node
  const texNode = texture(bgTexture);
  const planeMat = new MeshBasicNodeMaterial({
    colorNode: texNode,
    transparent: true,
  });
  disposables.push(planeMat);

  // Create plane mesh
  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  group.add(planeMesh);

  // Render text "Features 2" (headline = 0.34 scene units)
  if (config.textContent) {
    let textStr = config.textContent;
    if (Array.isArray(textStr)) textStr = textStr[0];
    if (typeof textStr === 'object' && textStr.text) textStr = textStr.text;

    if (textStr) {
      const textMesh = ctx.fontAtlas.createTextMesh(textStr, {
        fontSize: 0.34,
        fontFamily: 'Lora',
        fontWeight: 400,
        color: '#16161d',
        anchorX: 'center',
        anchorY: 'middle',
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        group.add(textMesh);
        if (textMesh.geometry) disposables.push(textMesh.geometry);
        if (textMesh.material) disposables.push(textMesh.material);
      }
    }
  }

  // Apply scene position
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);

    if (rotationXYZ && rotationXYZ.length === 3) {
      group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2], 'XYZ');
    }

    if (scaleXYZ && scaleXYZ.length === 3) {
      group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    disposables.forEach(item => {
      if (item && typeof item.dispose === 'function') {
        item.dispose();
      }
    });
  };

  // Event handlers (no interactivity)
  group.userData.handlers = {};

  return group;
}
